CREATE TABLE whatsapp_offers (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, selected_product_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, code VARCHAR(32) NOT NULL, name VARCHAR(160) NOT NULL, units INT NOT NULL, price_mode VARCHAR(8) NOT NULL, fixed_price DECIMAL(14,2) NULL, landing_default TINYINT(1) NOT NULL DEFAULT 0, status VARCHAR(10) NOT NULL DEFAULT 'active', created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY (id), UNIQUE KEY whatsapp_offers_code_uq (user_id,code), UNIQUE KEY whatsapp_offers_owner_uq (id,user_id), CONSTRAINT whatsapp_offers_units_ck CHECK (units BETWEEN 1 AND 99), CONSTRAINT whatsapp_offers_mode_ck CHECK (price_mode IN ('tiers','fixed')), CONSTRAINT whatsapp_offers_price_ck CHECK (fixed_price IS NULL OR fixed_price >= 0), CONSTRAINT whatsapp_offers_status_ck CHECK (status IN ('active','archived')), CONSTRAINT whatsapp_offers_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT whatsapp_offers_product_fk FOREIGN KEY (selected_product_id,user_id) REFERENCES selected_products(id,user_id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci